function reorderPinnedCardsWithoutRebuild(){
 const cards=Array.from(els.list.querySelectorAll('.reminder-card'));
 if(!cards.length)return;
 const positions=new Map(cards.map((card,i)=>[card.dataset.id,i]));
 const items=cards.map(card=>({card,reminder:reminders.find(r=>r.id===card.dataset.id)}));
 const groups=new Map();
 for(const entry of items){
  const section=entry.reminder?manualOrderKey(entry.reminder):'unknown';
  if(!groups.has(section))groups.set(section,[]);
  groups.get(section).push(entry);
 }
 for(const entries of groups.values()){
  const sorted=entries.slice().sort((a,b)=>{
   if(!a.reminder||!b.reminder)return 0;
   if(els.sort.value==='priority'&&canManualReorder()){
    const state=manualOrderState(),ai=manualOrderIndex(a.reminder,state),bi=manualOrderIndex(b.reminder,state);
    if(ai!==bi)return ai-bi;
   }
   if(Boolean(a.reminder.pinned)!==Boolean(b.reminder.pinned))return a.reminder.pinned?-1:1;
   return positions.get(a.card.dataset.id)-positions.get(b.card.dataset.id);
  });
  const first=entries[0].card;
  const marker=document.createComment('pin-order');first.before(marker);
  const fragment=document.createDocumentFragment();
  for(const item of sorted)fragment.appendChild(item.card);
  marker.replaceWith(fragment);
 }
}
